CREATE OR REPLACE FUNCTION beta_private.admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='UPDATE' and old.status in('suspended','revoked') and new.user_id is null
 and (to_jsonb(new)-array['email','user_id'])=(to_jsonb(old)-array['email','user_id'])
 and beta_private.privacy_redaction_allowed(old.user_id,new.email) then return new;end if;
 update beta_private.admission_control set admission_revision=admission_revision+1 where id;
 if tg_op='DELETE' then raise exception 'Admission history is permanent'; end if;
 if tg_op='UPDATE' and (to_jsonb(new)-array['status','accepted_at','country','state','age_attested','policy_digest','policy_versions','token_digest','expires_at'])
 is distinct from (to_jsonb(old)-array['status','accepted_at','country','state','age_attested','policy_digest','policy_versions','token_digest','expires_at']) then
 raise exception 'Invitation identity and token are immutable'; end if;
 if tg_op='INSERT' or new.token_digest is distinct from old.token_digest then
 if new.expires_at<=clock_timestamp() or new.expires_at>clock_timestamp()+interval '7 days' or new.status<>'reserved' then raise exception 'Invitation expiry required within seven days';end if;
 end if;
 if new.administrator and (new.user_id is null or not exists(select 1 from beta_private.designated_administrators where user_id=new.user_id)) then
 raise exception 'Explicit designated administrator required'; end if;
 if tg_op='INSERT' and not new.administrator and (select count(*) from beta_private.admissions where not administrator)>=10 then
 raise exception 'Ten tester lifetime admission limit'; end if;
 if tg_op='UPDATE' and (old.status in('revoked','suspended') or (old.status='accepted' and new.status not in('revoked','suspended') and not (
 new.status='accepted' and (to_jsonb(new)-array['policy_digest','policy_versions'])=(to_jsonb(old)-array['policy_digest','policy_versions'])
 and new.user_id=auth.uid() and exists(select 1 from beta_private.admission_control c where c.enabled and c.policy_digest=new.policy_digest and c.policy_versions=new.policy_versions)
 and exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.user_id=new.user_id and s.id=(auth.jwt()->>'session_id')::uuid and (s.not_after is null or s.not_after>clock_timestamp()) and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false))
 and (not beta_private.gameplay_mfa_required(new.user_id) or auth.jwt()->>'aal'='aal2')))) then
 raise exception 'Invalid admission transition'; end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION beta_private.admitted_before_owner_gameplay(p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare ok boolean;begin
 perform 1 from beta_private.admission_control where id for share;
 perform 1 from beta_private.admissions where user_id=p_user for share;
 select exists(select 1 from beta_private.admissions a cross join beta_private.admission_control c
 where c.enabled and (a.administrator or c.testers_enabled) and a.user_id=p_user and a.status='accepted' and a.country='AU' and a.age_attested
 and a.policy_digest=c.policy_digest and a.policy_versions=c.policy_versions) into ok;
 return ok;
end$function$

CREATE OR REPLACE FUNCTION beta_private.renew_customer_consent(p_user uuid, p_session uuid, p_country text, p_state text, p_versions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a beta_private.admissions; c beta_private.admission_control; purpose text;begin
 select * into strict c from beta_private.admission_control where id for update;
 select * into strict a from beta_private.admissions where user_id=p_user for update;
 if not c.enabled or p_user is distinct from auth.uid() or (auth.jwt()->>'session_id')::uuid is distinct from p_session or p_versions is distinct from c.policy_versions or not beta_private.beta_gameplay_identity(p_user) or a.status<>'accepted' or p_country is distinct from a.country or p_state is distinct from a.state then raise exception 'Existing active consent identity required';end if;
 if beta_private.gameplay_mfa_required(p_user) and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'Privileged MFA required';end if;
 if not exists(select 1 from auth.users u join auth.sessions s on s.user_id=u.id where u.id=p_user and s.id=p_session and (s.not_after is null or s.not_after>clock_timestamp()) and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false)) then raise exception 'Verified session required';end if;
 if a.policy_versions=c.policy_versions and a.policy_digest=c.policy_digest then return;end if;
 update beta_private.admissions set policy_digest=c.policy_digest,policy_versions=c.policy_versions where id=a.id;
 update beta_public.profiles set accepted_version=c.policy_versions->>'terms' where id=p_user;
 foreach purpose in array array['terms','privacy','age_attestation'] loop
  insert into beta_private.consent_events(user_id,purpose,granted,version,actor) values(p_user,purpose,true,c.policy_versions->>(case when purpose='privacy' then 'privacy' else 'terms' end),p_user::text);
 end loop;
 insert into beta_private.admission_events(admission_id,action,actor,details) values(a.id,'policy_reaccepted',p_user::text,jsonb_build_object('previous',a.policy_versions,'resulting',c.policy_versions));
end$function$
